# Copy for the "AI numbers, checked" 14-day series. Run: python3 posts.py → posts.json + posts.md
import json,re
F='https://report-ai.org/reports/ai-statistics-fact-check/'
P=[
dict(n=1,img='01-fact-check-register.png',link=F,
 x="We traced 13 of the most-quoted AI statistics back to their sources.\n\n2 are wrong outright. 4 are misdescribed or overstated. 3 are out of date. 4 can't be traced or are forecasts quoted as fact.\n\nThe register:",
 long="We traced 13 of the most-quoted AI statistics back to their sources.\n\n2 are wrong outright. 4 are misdescribed or overstated. 3 are out of date. 4 are untraceable, contested, or forecasts quoted as fact.\n\nAlmost none was invented. They drift: a broad measurement gets a narrow label, a unit gets lost in translation, a forecast becomes a \"fact\" when its year arrives, and a correct figure keeps circulating without its date.\n\nIt matters more in AI than anywhere else, because AI systems learn from the repeated, undated versions.\n\nFor the next 14 days we'll post one of them a day, with the chart.",
 alt="Bar chart of Report AI's verdicts on 13 widely quoted AI statistics: 4 misdescribed or overstated, 4 untraceable, contested or a forecast, 3 superseded or out of date, 2 wrong outright."),
dict(n=2,img='02-pentagon-500b.png',link=F+'#fc-pentagon-500b',
 x="\"A fake AI image of a Pentagon explosion wiped $500B off US stocks.\"\n\nThe reported S&P 500 dip (~0.26%, or ~30 points) implies roughly $90B–$250B. $500B would need a ~1.4% fall.\n\nOne multiplication:",
 long="\"A fake AI image of a Pentagon explosion wiped $500 billion off the US stock market.\"\n\nIt's been repeated for three years. Nobody seems to have done the multiplication.\n\nOn 22 May 2023 the S&P 500 dipped briefly: about 0.26% on the figure most incident records use, about 30 points in some reports. On an index worth roughly $34–36 trillion, that implies about $90 billion to $250 billion.\n\nReaching $500 billion would take a fall of about 1.4%. We found no source that shows how $500 billion was calculated.\n\n(Our arithmetic, rated DERIVED; the inputs are on the page.)",
 alt="Bar chart: the commonly claimed $500 billion stock-market loss from a fake Pentagon image, against $250 billion and $90 billion implied by the reported 30-point and 0.26% S&P 500 dips."),
dict(n=3,img='03-doubao-382m.png',link=F+'#fc-doubao',
 x="\"Doubao has 3.8 billion users.\"\n\nThe Chinese figure was 3.8亿. One 亿 = 100 million. So: ~382 million monthly users, not 3.8 billion.\n\nA tenfold error, published as a headline.",
 long="\"Doubao has 3.8 billion users.\"\n\nAt least one English-language outlet ran that as a headline.\n\nThe Chinese figure is 3.8亿. One 亿 is a hundred million, so 3.8亿 is about 380 million: QuestMobile's 382 million monthly active users. The headline overstated it tenfold.\n\nThe unit conversion is certain (HIGH). The 382 million itself is a device-panel estimate, which we rate MEDIUM.\n\nChinese user numbers are where this error happens most. 万 (10,000) and 亿 (100 million) don't map neatly onto thousands and millions.",
 alt="Bar chart: a claimed 3.8 billion Doubao users against the actual 382 million monthly users. The Chinese figure 3.8亿 means about 380 million."),
dict(n=4,img='04-dev-review-inversion.png',link='https://report-ai.org/indexes/workforce-labor/will-ai-replace-my-job/software-developers/',
 x="In Q1 2026, reviewing AI-generated code overtook writing code: 11.4 hours a week vs 9.8.\n\nMedian PR review time: +441%. PRs merged with no review at all: +31%.\n\nThe bottleneck moved.",
 long="Code generation worked. That was never the constraint.\n\nIn Q1 2026, reviewing AI-generated code overtook writing code as the biggest use of developer time: 11.4 hours a week against 9.8.\n\nWhat happened to the review queue (Faros AI):\n• Median time a pull request sits in review: +441%\n• Pull request size: +51%\n• Bugs per developer: +54% (+28.7% per PR, the volume-controlled figure)\n• Pull requests merged with no review at all: +31%\n\nWhen verification becomes the bottleneck and nobody resources it, the queue doesn't get shorter. It gets skipped.\n\nAll figures MEDIUM; sources on the page.",
 alt="Column chart: developers spend 11.4 hours a week reviewing AI-generated code against 9.8 hours writing new code, Q1 2026."),
dict(n=5,img='05-support-deflection.png',link='https://report-ai.org/indexes/workforce-labor/will-ai-replace-my-job/customer-support/',
 x="AI support vendors quote 70–90% deflection.\n\nThe enterprise median is 41.2%. Bottom quartile: 22.4%.\n\nAnd AI-resolved tickets come back more often: 11.3% re-contact vs 8.7% for human-resolved.",
 long="AI support vendors quote 70–90% deflection.\n\nThe median across enterprise programmes is 41.2%. The top quartile reaches 58.7%; the bottom quartile 22.4%.\n\nThe average hides what matters: what the customer asked about. Password resets, order status and refunds deflect at 70%+. Nuanced complaints rarely break 25%.\n\nThen the number most business cases miss: AI-resolved tickets are re-contacted 11.3% of the time, against 8.7% for human-resolved ones. A plan built on 70% deflection and delivered at 41% leaves about 30% of volume unaccounted for, and it is the hard 30%.\n\nMEDIUM confidence; benchmarks on the page.",
 alt="Bar chart of tier-1 AI deflection rates: vendor claims of 70% at the low end, top quartile 58.7%, median 41.2%, bottom quartile 22.4%."),
dict(n=6,img='06-meta-project-ot.png',link='https://report-ai.org/reports/ai-replacement-reversal-2026/',
 x="Meta measured its own AI restructuring (CTO, June 2026):\n\nCode changes to internal platforms: +220%\nChanges reaching users: +36%\nMajor incidents: +40%\nFirefighting time: +70%\n\nThe second wave of cuts was cancelled.",
 long="Meta measured its own AI restructuring. CTO Andrew Bosworth's June 2026 figures, year on year:\n\nCode changes to internal platforms: +220%\nChanges reaching users as features: +36%\nMajor technical and security incidents: +40%\nTime spent firefighting them: +70%\n\nOutput tripled. Shipped value grew by about a third. Incidents and cleanup grew faster than the value did.\n\nThe second planned wave of cuts never happened.\n\nThe lesson isn't that the tools failed. The system around them (review, security, incident response) was sized for the old volume.",
 alt="Bar chart of Meta's year-on-year changes: code changes to internal platforms +220%, time spent firefighting incidents +70%, major technical and security incidents +40%, changes reaching users as features +36%."),
dict(n=7,img='07-layoff-reversal.png',link='https://report-ai.org/reports/ai-replacement-reversal-2026/',
 x="55% of employers regret AI-related layoffs. 32% of roles cut \"because of AI\" are already refilled.\n\nOf companies that reversed: 30.9% spent more than automation saved and 42.4% roughly broke even.\n\nThat's ~73% no better off.",
 long="55% of employers regret laying off workers for AI-related reasons (Forrester). 32% of roles cut \"because of AI\" have already been refilled (Robert Half).\n\nThe part nobody models: of organisations that reversed, 30.9% spent more on rehiring than automation saved them, and another 42.4% roughly broke even. That's about three-quarters no better off than if they'd never cut. (The 73% is our sum, labelled DERIVED.)\n\nRehired roles also come back at a 20–35% salary premium, as hybrid positions.\n\nA business case that doesn't price the reversal is a forecast of the good outcome.",
 alt="Bar chart: 55% of employers regret AI layoffs, 42.4% of reversals roughly broke even, 32% of roles cut because of AI already refilled, 30.9% of reversals cost more than they saved."),
dict(n=8,img='08-deepfake-record.png',link='https://report-ai.org/reports/dark-side-of-ai/ai-deepfake-fraud-statistics/',
 x="The \"$25M Arup deepfake\" is no longer the record.\n\nIn Sept 2026, fraudsters took €95M (~$108M) from Fideuram using a WhatsApp message and a cloned executive voice. No video at all.\n\n~€36M reportedly unrecovered.",
 long="Most deepfake-statistics pages still say the record is Arup: about $25 million lost on a 2024 video call where every other participant was synthetic.\n\nIt isn't any more. In September 2026 Reuters reported that fraudsters impersonating senior executives took €95 million (about $108 million) from Fideuram, the private-banking arm of Intesa Sanpaolo, using a WhatsApp message and an AI-cloned voice. No video at all. About €36 million is reported unrecovered.\n\nFor scale: the FBI's 2025 Internet Crime Report counted 22,364 complaints with an AI descriptor and $893 million in losses.\n\nMEDIUM confidence.",
 alt="Column chart comparing record deepfake frauds: Arup, $25 million in 2024, and Fideuram, about $108 million in 2026."),
dict(n=9,img='09-chatgpt-users.png',link=F+'#fc-chatgpt-800m',
 x="\"ChatGPT has 800 million weekly users\" was true in Oct 2025. The 2026 figure is 900M+.\n\nAnd \"2.8 billion monthly users\"? No disclosure supports it. That would be a third of humanity.\n\nThe series:",
 long="Two ChatGPT numbers are going round. Both are wrong, in different ways.\n\n\"800 million weekly users\" is out of date. It was OpenAI's figure for October 2025. The series runs 400 million (Feb 2025), ~700 million (Jul 2025), 800 million (Oct 2025), 900 million+ (2026).\n\n\"2.8 billion monthly users\" is unsupported. We found no disclosure or measurement behind it, and it would be roughly a third of the world's population.\n\nA figure without its date gets re-quoted as current. AI models do the same.",
 alt="Column chart of ChatGPT weekly active users disclosed by OpenAI: 400 million in February 2025, 700 million in July 2025, 800 million in October 2025, more than 900 million in 2026."),
dict(n=10,img='10-time-to-1m.png',link='https://report-ai.org/reports/ai-user-numbers-us-china-compared/',
 x="ChatGPT reached 1 million users in 5 days. DeepSeek took 14.\n\nGemini, Copilot and Meta AI have no comparable figure. They never \"reached\" a million users; they were switched on for hundreds of millions of existing accounts.",
 long="ChatGPT reached a million users in 5 days (Greg Brockman said so on day five). DeepSeek took 14.\n\nGemini, Copilot and Meta AI have no comparable figure, because they never reached a million users. They were switched on inside products that already had hundreds of millions of accounts.\n\nRanking a bundled rollout against a cold start is a category error. The only clean AI-to-AI comparison is ChatGPT against DeepSeek.\n\nAnd DeepSeek's curve is the more interesting one: slower to its first million, then roughly 100 million users in a week at the end of January 2025.",
 alt="Bar chart of time to one million users: ChatGPT 5 days in November 2022, DeepSeek 14 days in January 2025."),
dict(n=11,img='11-token-prices.png',link='https://report-ai.org/indexes/ai-economics/llm-token-price-index/',
 x="What does a million AI tokens cost?\n\n97 cents: the usage-weighted market average, a record low (1 Sep 2026).\n$50: Fable 5.1 output, same date.\n\nBoth true. Mixing them up is the most common error in AI pricing coverage.",
 long="What does a million AI tokens cost? Two true answers, on the same day.\n\n97 cents: Silicon Data's usage-weighted LLM Token Expenditure Index on 1 September 2026, a record low and less than half its earlier peak.\n\n$50: Anthropic's Fable 5.1 output price per million tokens ($10 input).\n\nThe index measures what the market actually pays, and the market is dominated by cheap and mid-tier models. It is not the price of frontier capability.\n\nUnit prices are falling while total bills rise, because agentic workloads burn far more tokens per task.",
 alt="Bar chart of price per million tokens: Fable 5.1 output $50, Opus 5.5 output $20, Sonnet 5.5 output $10, and the usage-weighted market average $0.97."),
dict(n=12,img='12-datacenter-energy.png',link='https://report-ai.org/indexes/technical-benchmarks/ai-energy-water-per-query/',
 x="One AI prompt: ~0.24 Wh of electricity and ~0.26 mL of water (median Gemini text prompt, Google).\n\nAll data centers: ~415 TWh in 2024, heading for ~945 TWh by 2030 (IEA).\n\nThe per-query number isn't the story.",
 long="Both of these are true:\n\nA median Gemini text prompt uses about 0.24 Wh of electricity and 0.26 mL of water (Google, Aug 2025), close to a web search. The 2.9 Wh figure that circulated in 2023–24 is roughly 10× too high for today's models.\n\nGlobal data-center electricity was about 415 TWh in 2024 and the IEA projects about 945 TWh by 2030. Roughly a doubling, with AI the main driver.\n\nPer-query estimates vary 10× or more with model size, cooling overhead and grid mix. Treat any single figure with caution. The fleet total is the number that matters.",
 alt="Column chart of global data-center electricity use: 415 terawatt-hours in 2024 and a projected 945 terawatt-hours in 2030."),
dict(n=13,img='13-chatbot-false-claims.png',link='https://report-ai.org/reports/dark-side-of-ai/ai-slop-content-pollution-internet/',
 x="How often do leading chatbots repeat false news claims? NewsGuard's audits:\n\nAug 2024: 18%\nAug 2025: 35%\nJan 2026: 28.8%\n\nThe widely shared \"62%\" isn't in any NewsGuard audit we could find.",
 long="How often do leading AI chatbots repeat false news claims?\n\nNewsGuard's monthly audits: 18% in August 2024, 35% in August 2025, 28.8% in January 2026. NewsGuard attributes the rise largely to chatbots now answering questions they used to decline.\n\nYou may have seen \"62%\". We couldn't trace it to any NewsGuard audit, so we withdrew it from our own page and logged the correction.\n\nMeanwhile NewsGuard tracks 3,749 AI content-farm news sites across 16 languages (June 2026), nearly three times its 2025 count.\n\nMEDIUM confidence.",
 alt="Column chart of how often leading chatbots repeated false news claims in NewsGuard audits: 18% in August 2024, 35% in August 2025, 28.8% in January 2026."),
dict(n=14,img='14-claude-users.png',link=F+'#fc-claude',
 x="How many people use Claude? Published estimates for the same period run from 56M to 245M monthly users, a 4.4× spread.\n\nThey mix weekly and monthly, web traffic and app installs. Anthropic doesn't publish a count.",
 long="How many people use Claude?\n\nPublished estimates for the same period range from 56 million to 245 million monthly users. That's a 4.4-fold spread, and it isn't noise. It's method: some count weekly users, some monthly; some measure web traffic, some app installs. Anthropic doesn't publish a consumer user count.\n\nAny single figure should come with its method, or as a range. That's what we publish.\n\nThat's the last of the 14. Every figure from this series, with its source, date and confidence rating, is in the fact-check register.",
 alt="Bar chart of published estimates of Claude's monthly users for the same period: highest 245 million, lowest 56 million, a 4.4-fold spread."),
]
def xlen(s): return len(re.sub(r'https?://\S+','x'*23,s))
out=[]
for p in P:
    x=p['x']+'\n'+p['link']; li=p['long']+'\n\n'+p['link']
    th=p['x']+'\n'+p['link']
    ig=p['long']+'\n\nFull data, sources and confidence ratings at report-ai.org (link in bio).\n\n#AI #ArtificialIntelligence #Data #FactCheck #ReportAI'
    assert xlen(x)<=280,(p['n'],xlen(x)); assert len(th)<=500,(p['n'],len(th)); assert len(ig)<=2200
    out.append(dict(day=p['n'],image=p['img'],link=p['link'],alt=p['alt'],x=x,linkedin=li,facebook=li,threads=th,instagram=ig,x_len=xlen(x)))
json.dump(out,open('posts.json','w'),ensure_ascii=False,indent=1)
print([o['x_len'] for o in out])
